steps.command:
curl -sS --fail-with-body -H "Content-Type: application/json" \
  -d '{
    "embeds": [{
      "title": "❌ Build Failed",
      "description": "**Workflow:** ${{ github.event.workflow_run.name }}\n**Branch:** ${{ github.event.workflow_run.head_branch }}\n**Commit:** ${{ github.event.workflow_run.head_sha }}",
      "url": "${{ github.event.workflow_run.html_url }}",
      "color": 15158332
    }]
  }' \
  "$DISCORD_WEBHOOK_URL"

$files = @(
  "dist-windows/Goose.exe",
  "dist-windows/resources/bin/goosed.exe"
)
foreach ($file in $files) {
  Write-Output "Verifying signature: $file"
  $sig = Get-AuthenticodeSignature $file
  if ($sig.Status -ne "Valid") { throw "Signature invalid for ${file}: $($sig.Status)" }
  Write-Output "Signature valid: $file"
}
